#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys


CURRENT_RELEASE = "2.0"
RELEASE_1_ACCOUNT_CAP_CENTS = 2400
RELEASE_2_SUBSCRIPTION_CAP_CENTS = 3000


def release_1_statement_credits(lines):
    """Return assigned release 1.0 credits keyed by line ID."""
    credits = {}
    lines_by_account = {}

    for line in lines:
        lines_by_account.setdefault(line["account_id"], []).append(line)

    for account_lines in lines_by_account.values():
        remaining_credit = RELEASE_1_ACCOUNT_CAP_CENTS
        for line in sorted(
            account_lines, key=lambda item: (item["service_on"], item["line_id"])
        ):
            uncapped_credit = line["charge_cents"] // 10
            assigned_credit = min(uncapped_credit, remaining_credit)
            credits[line["line_id"]] = assigned_credit
            remaining_credit -= assigned_credit

    return credits


def release_2_statement_credits(lines):
    """Return assigned release 2.0 credits keyed by line ID."""
    credits = {}
    lines_by_subscription = {}

    for line in lines:
        subscription = (line["account_id"], line["subscription_id"])
        lines_by_subscription.setdefault(subscription, []).append(line)

    for subscription_lines in lines_by_subscription.values():
        remaining_credit = RELEASE_2_SUBSCRIPTION_CAP_CENTS
        for line in sorted(
            subscription_lines,
            key=lambda item: (-item["charge_cents"], item["line_id"]),
        ):
            uncapped_credit = line["charge_cents"] * 15 // 100
            assigned_credit = min(uncapped_credit, remaining_credit)
            credits[line["line_id"]] = assigned_credit
            remaining_credit -= assigned_credit

    return credits


def statement_credits(lines, release):
    if release == "1.0":
        return release_1_statement_credits(lines)
    if release == "2.0":
        return release_2_statement_credits(lines)
    raise ValueError(f"unsupported release: {release}")


def quote(line, release):
    credit_cents = statement_credits([line], release)[line["line_id"]]
    return {
        "release": release,
        "credit_cents": credit_cents,
        "amount_due_cents": line["charge_cents"] - credit_cents,
        "line_id": line["line_id"],
    }


def total(lines, release):
    credits = statement_credits(lines, release)
    credit_cents = sum(credits.values())
    charge_cents = sum(line["charge_cents"] for line in lines)
    return {
        "release": release,
        "credit_cents": credit_cents,
        "amount_due_cents": charge_cents - credit_cents,
    }


def handle(request):
    command = request.get("command")
    if command == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if command == "quote":
        release = request.get("release", CURRENT_RELEASE)
        return quote(request["line"], release)
    if command == "total":
        release = request.get("release", CURRENT_RELEASE)
        return total(request["lines"], release)
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")

